window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d02_pe2019"]={"title": "Проект эксплуатации пруда-накопителя, 2019–2021", "pages": 56, "pagesTxt": ["[стр. 1]\nАКЦИОНЕРНОЕ ОБЩЕСТВО \n«МЕХАНОБР ИНЖИНИРИНГ» \nЗАПОЛЯРНЫЙ ФИЛИАЛ \nПАО ГОРНО-МЕТАЛЛУРГИЧЕСКАЯ КОМПАНИЯ \n\"НОРИЛЬСКИЙ НИКЕЛЬ\" \n \n \nТОФ \nПруд-накопитель \nТалнахской обогатительной фабрики \n \nПРОЕКТ ЭКСПЛУАТАЦИИ 2019-2021 гг. \n(КОРРЕКТИРОВКА ПО РЕЗУЛЬТАТАМ ВЫПОЛНЕННЫХ ИЗЫСКАНИЙ) \nШИФР 33016-25 \nНачальник гидротехнического отдела                                  А.М.Бабич \n \nСанкт-Петербург \n2019 г.", "[стр. 2]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”  33016 – 25 - РХХ  2\nСкиргайло В.В    C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nСписок исполнителей \nДолжность Подпись Фамилия Дата \nГлавный специалист  Н.А. Филатова  \nРуководитель группы  В.В. Скиргайло  \nВедущий инженер  Н.С. Смирнова", "[стр. 3]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”  33016 – 25 - РХХ  3\nСкиргайло В.В    C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n \nОглавление \n1. ВВЕДЕНИЕ ...................................................................................................................................... 5 \n2. КРАТКИЕ КЛИМАТИЧЕСКИЕ И ИНЖЕНЕРНО-ГЕОЛОГИЧЕСКИЕ УСЛОВИЯ РАЙОНА ПРУДА-\nНАКОПИТЕЛЯ .................................................................................................................................. 7 \n2.1. Физико-географические условия площадки ....................................................................... 7 \n2.2. Климатические условия района .......................................................................................... 8 \n2.3. Инженерно-геологические, инженерно-гидрологические и сейсмические условия \nплощадки пруда-накопителя. .............................................................................................. 8 \n3. Существующие сооружения комплекса пруда-накопителя .................................................... 15 \n3.1 Основные параметры и характеристики сооружений ...................................................... 15 \n3.2 Основные технологические процессы ............................................................................... 18 \n4. БАЛАНС ВОДЫ В ПРУДЕ-НАКОПИТЕЛЕ ............................................................................................ 23 \n5. ЭКСПЛУАТАЦИЯ СООРУЖЕНИЙ КОМПЛЕКСА ПРУДА-НАКОПИТЕЛЯ ................................................... 24 \n5.1 Ограждающая дамба .......................................................................................................... 24 \n5.2 Насосные установки ........................................................................................................... 26 \n5.3 Напорные и самотечные трубопроводы ........................................................................... 28 \n5.4 Отстойный пруд ................................................................................................................... 29 \n5.5 Контрольно-измерительная аппаратура ........................................................................... 31 \n6. КОНТРОЛЬ И НАБЛЮДЕНИЯ ЗА СОСТОЯНИЕМ СООРУЖЕНИЙ ПРУДА-НАКОПИТЕЛЯ .......................... 34 \n7. КРИТЕРИИ БЕЗОПАСНОСТИ ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЙ .................................................... 41 \n8. МЕРОПРИЯТИЯ ПО ПРЕДУПРЕЖДЕНИЮ ЧРЕЗВЫЧАЙНЫХ СИТУАЦИЙ .............................................. 43 \n9. ШТАТЫ ......................................................................................................................................... 48 \n10. ЭКСПЛУАТАЦИОННАЯ ТЕХНИКА ................................................................................................... 50 \n11. ОСНОВНЫЕ ПОЛОЖЕНИЯ ПО ТЕХНИКЕ БЕЗОПАСНОСТИ ............................................................... 51 \nПриложение «А» - чертеж 359335-ГТ, «Норильскпроект» ..................................................... 54 \nПриложение «Б» - чертежи 30916-ГИ-14; 15, ЗАО «МИ» ...................................................... 55 \nПриложение «В» - чертеж 358992-ТК0.1, «Норильскпроект» ................................................ 56", "[стр. 4]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”  33016 – 25 - РХХ  4\nСкиргайло В.В    C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nПеречень рисунков  \n \n№№ \nпп \nНаименование Обозначение №№ \nстр. \nПримечание \n1 Технологическая схема функционирования \nпруда-накопителя \nрис. 1 16 Раздел 3.1 \n2 Схема размещения контрольно-\nизмерительной аппаратуры. \nрис. 2 31 Раздел 5.5 \n \nПеречень таблиц  \n№№ \nпп \nНаименование Обозначение №№ \nстр. \nПримечание \n1 Физико-механические характеристики грун-\nтов основания \nТаблица 1 \n \n11 Раздел 2. 3 \n2 Гранулометрический, химический и минера-\nлогический состав твердого \nТаблица 2 18-19 Раздел 3.2 \n3 Химический состав сточных вод, поступаю-\nщих в пруд-накопитель \nТаблица 3 19-20 Раздел 3.2 \n4 Баланс воды в пруде-накопителе Таблица 4 21 Раздел 4 \n5 Данные для определения ледяного покрова Таблица 5 29 Раздел 5.4 \n6 Ведомость вторичных приборов и инстру-\nментов \nТаблица 6 30 Раздел 5.5 \n7 Перечень объектов мониторинга безопасно-\nсти гидротехнических сооружений \nТаблица 7 32 Раздел 6 \n8 Ведение мониторинга безопасности на пру-\nде-накопителе ТОФ \nТаблица 8 35-37 Раздел 6 \n9 Эксплуатационный персонал Таблица 9 44 Раздел 9 \n10 Эксплуатационная техника Таблица 10 45 Раздел 10", "[стр. 5]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  5\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n1. ВВЕДЕНИЕ \nНастоящий \" Проект эксплуатации пруда-накопителя Талнахской обогати-\nтельной фабрики ( ТОФ Заполярного филиала ПАО \" Горно-металлургическая \nкомпания \"Норильский никель\" (ЗФ ПАО \"ГМК\" \"НН\") откорректирован АО \"Ме-\nханобр инжиниринг\" в соответствии с договором № 73-27-05/192-2665/05 от 9 \nноября 2005 г. № 73-18-16/88-2424/16 от 23.10.2016 \nПроект выполнен в рамках дополнительного соглашения №4 « Оказание \nинжиниринговых услуг» к указанному выше договору, этап 5. \nПроект разработан на основании выписки из реестра членов саморегули-\nруемой организации Ассоциации « Проектные организации Северо-Запада» от \n06.10.2018 №П-408-023.  \nПруд-накопитель входит в состав внешней системы оборотного водоснаб-\nжения Талнахской обогатительной фабрики. В пруд-накопитель направляются \nсливы сгущения концентратов НМЗ и промпродуктов ТОФ, а также аварийные \nпереливы ПНС-1. Пруд-накопитель введен в эксплуатацию в 1981 году. \nОсновной функцией пруда-накопителя является отстаивание и кондицио-\nнирование поступающей жидкой фазы перед повторным ее использованием в \nтехнологии Талнахской обогатительной фабрики. Емкость пруда используется \nтакже как буферная. Поступающие с переливами зумпфов металлосодержа-\nщие материалы возвращаются обратно на ТОФ с помощью земснаряда и \nнапорного гидротранспорта.  \nВ проекте определены основные положения по эксплуатации сооружений \nпруда-накопителя ТОФ на 2019 ÷ 2021 гг. с учетом существующего состояния \nпруда-накопителя. \nВ проекте выполнен анализ работы пруда-накопителя за период до 2018 \nг., анализ состояния действующих сооружений, относящихся к системе оборот-\nного водоснабжения и гидротранспорта шламов, разработаны и рекомендова-\nны мероприятия по обеспечению надежности и безопасности эксплуатации \nпруда-накопителя ТОФ. \nВ настоящем проекте даны рекомендации по эксплуатации комплекса со-\nоружений пруда-накопителя, а также по проведению работ по осуществлению \nконтроля и наблюдений за состоянием сооружений пруда-накопителя. \nПри разработке проекта учитывались: \n― Прием на осветление технологических стоков ( сливы сгустителей \nпромпродуктов ТОФ; сливы сгустителей НМЗ; оборотная вода из хво-\nстохранилища ТОФ (I очередь);", "[стр. 6]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  6\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n― Аккумуляция водопритока в пруд-накопитель с водосборной площади, \nравной 0,26 км2. \nПроект эксплуатации выполнен в соответствии с требованиями действую-\nщих норм, СНиПов и \" Правил безопасности гидротехнических сооружений \nнакопителей жидких промышленных отходов\", ПБ-03-438-02, утвержденных \nГосгортехнадзором России 28.01.2002 г. \nПри выполнении данной работы были использованы следующие материа-\nлы: \n1. Проектно-сметная документация института \" Механобр\" шифр 20226-\n401. \n2. Проектно-сметная документация АО \" Механобр инжиниринг\" шифр \n30916-ГИ-1, 11, 12. \n3. \" Технический отчет об инженерно-геологических изысканиях по объек-\nту: «ТОФ. Реконструкция и техническое перевооружение ТОФ с увели-\nчением мощности до 18 млн. тонн по сумме руд. Корректировка 3 Пус-\nкового комплекса» № 356662- ИГ-662. 2018 г. выполненным ООО « Но-\nрильскгеология»  \n4. \" Проект мониторинга безопасности гидротехнических сооружений пру-\nда-накопителя ТОФ\", ЗАО \" Механобр инжиниринг\", шифр 33016-23, \n2010г. \n5. Годовой отчет по пруду-накопителю за 2017-2018 год. \n6. \" Декларация безопасности пруда-накопителя Талнахской обогатитель-\nной фабрики\", ЗАО \" Механобр инжиниринг\", шифр 33016-42- ДБГ, 2016 \nг., \n7. « Критерии безопасности гидротехнических сооружений пруда-\nнакопителя Талнахской обогатительной фабрики», ЗАО \" Механобр ин-\nжиниринг\", шифр 33016-22, 2019 год.", "[стр. 7]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  7\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n2. КРАТКИЕ КЛИМАТИЧЕСКИЕ И ИНЖЕНЕРНО-ГЕОЛОГИЧЕСКИЕ \nУСЛОВИЯ РАЙОНА ПРУДА-НАКОПИТЕЛЯ \nОписываемая площадка расположена у подножья Лесной гряды, являю-\nщейся останцом плато Хараелах. ГТС пруда-накопителя Талнахской обогати-\nтельной фабрики расположены на плато Хараелах, на расстоянии ~ 3,25 км от \nреки Хараелах (Еловая) и 1.2 км от реки Талнах. Площадка пруда расположена \nв 800 м юго-западнее площадки Талнахской обогатительной фабрики. С севе-\nра-востока пруд-накопитель ограничен естественным рельефом и автодорогой. \n2.1. Физико-географические условия площадки \nРельеф площадки западинно-бугристый, низкий. \nЕстественный рельеф сохранился с юго-западной стороны площадки пру-\nда-накопителя. Абсолютные отметки естественного рельефа изменяются в \nпределах 51-66 м с общим уклоном поверхности в юго-западном направлении. \nИз основных физико-геологических процессов и явлений на площадке \nпруда-накопителя можно выделить процессы морозного пучения, связанные с \nпромерзанием подозерных и подрусловых таликов, процессы термоэррозии \nпри оттаивании льдистых грунтов сезоннооттаивающего слоя и воздействии \nозерных вод на береговую линию, сложенную льдистыми грунтами. \nТерритория, где сохранился естественный рельеф, покрыта кустарниковой \nи древесной растительностью, характерной для лесотундры. \nНа участках, примыкающих к дамбе, развиты физико-геологические про-\nцессы, связанные с деградацией мерзлоты в виде просадочных явлений на \nучастках распространения с поверхности льдистых грунтов. \nНормативная мощность слоя сезонного оттаивания в зоне распростране-\nния вечномерзлотных грунтов составляет для: \n— насыпных галечниковых, щебенистых и глыбовых грунтов — 3,0 м; \n— насыпных суглинков — 2,0 м; \n— суглинков и глин — 2,0 м; \n— торфа — 1,0 м. \nНормативная мощность слоя сезонного промерзания в зоне распростра-\nнения талых грунтов составляет для: \n— насыпных суглинков — 2,5 м; \n— суглинков и глин — 2,5 м; \n— щебенистых и глыбовых грунтов — 1-2 м.", "[стр. 8]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  8\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n2.2. Климатические условия района \nТерритория Енисейского севера и, в том числе, Норильского промышлен-\nного района относится к субарктическому климатическому поясу и расположе-\nна на стыке Атлантико-арктической и Атлантико-континентальной областей. \nКлимат района субарктический, характеризуется отрицательной средне-\nгодовой температурой воздуха, продолжительной зимой с сильными моро-\nзами и метелями, холодным и дождливым летом. \nСреднемесячная ( среднемноголетняя) температура воздуха с октября по \nмай отрицательная и равна -18,5оС. В течение пяти месяцев она ниже — 20оС, \nс июня по сентябрь выше 0оС с максимумом (32,2оС). \nПервые устойчивые морозы наступают 2 октября и заканчиваются 1 июня. \nПродолжительность периода с положительной среднесуточной темпера-\nтурой воздуха составляет 117 дней; продолжительность периода с отрица-\nтельной температурой воздуха 248 дней. \nАбсолютный максимум температуры воздуха +32,2 оС, абсолютный мини-\nмум — 56оС. Годовая амплитуда колебания температур около 90оС. \nСреднегодовая (многолетняя) температура воздуха — 9,5оС. \nАбсолютная влажность изменяется от 0,7мб в январе до 10,6мб июле. \nСреднегодовая абсолютная влажность — 3,8 мб, относительная — 74%; \nдефицит влажности — 1,5 мб. \nГодовая сумма осадков 561 мм. Суточный максимум осадков приходится \nна август — 44,2 мм. Число дней с осадками изменяется от 143 до 195. \nОбеспеченность суточных осадков распределяется следующим образом: \n0,1% — 120 мм; 0,5% — 98 мм; 1% — 75 мм; 2% — 65 мм; 5% — \n42 мм; 10% — 36 мм. \nСнежный покров устанавливается в третьей декаде сентября и исчезает в \nпервой половине июня. Число дней со снежным покровом — 226. Плотность \nснега перед снеготаянием в среднем 0,3 г/см3. \nМаксимальная скорость ветра достигает 40 м/сек. Число дней в году с \nгололедом 5÷32, с изморозью 35÷132. \n2.3. Инженерно-геологические, инженерно-гидрологические и сейсмиче-\nские условия площадки пруда-накопителя. \nИз основных физико-геологических процессов и явлений на площадке \nпруда-накопителя можно выделить процессы морозного пучения, связанные с \nпромерзанием подозерных и подрусловых таликов, процессы термоэррозии", "[стр. 9]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  9\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nпри оттаивании льдистых грунтов сезоннооттаивающего слоя и воздействии \nозерных вод на береговую линию, сложенную льдистыми грунтами. \nТерритория, где сохранился естественный рельеф, покрыта кустарниковой \nи древесной растительностью, характерной для лесотундры. На участках, при-\nмыкающих к дамбе, развиты физико-геологические процессы, связанные с де-\nградацией мерзлоты в виде просадочных явлений на участках распростране-\nния с поверхности льдистых грунтов. \nНормативная мощность слоя сезонного оттаивания в зоне распростране-\nния вечномерзлотных грунтов составляет для: \nнасыпных галечниковых, щебенистых и глыбовых грунтов — 3,0 м; \nнасыпных суглинков — 2,0 м; \nсуглинков и глин — 2,0 м; \nторфа — 1,0 м. \nНормативная мощность слоя сезонного промерзания в зоне распростра-\nнения талых грунтов составляет для: \nнасыпных суглинков — 2,5 м; \nсуглинков и глин — 2,5 м; \nщебенистых и глыбовых грунтов — 1-2 м. \nИнженерно-геологические условия площадки. \nПо данным инженерных изысканий, выполненных институтом ООО « Но-\nрильскгеология» в 2018 году, в районе действующего пруда-накопителя  в гео-\nлогическом строении площадки существующего пруда-отстойника принимают \nучастие отложения четвертичной системы, подстилаемые скальными грунтами \nпермской системы. \nРазрез четвертичных отложений на площадке существующего пруда-\nотстойника ( основания дамбы) слагают насыпные грунты-tIV, аллювиально-\nозерные отложения вальковской и арылахской толщ нерасчлененных-а-l III-IV \nvl-ar и гляциальные отложения наледнинской толщи-qIIInl. \nНасыпные грунты — суглинки, галечниковые, щебенистые и глыбовые \nгрунты магматических пород использовались при строительстве ограждающей \nдамбы и инспекторской дороги. Вскрытая мощность насыпных грунтов 1.0-11.0 \nм. \nАллювиально-озерные отложения вальковской и арылахской толщ нерас-\nчлененных представлены в основном суглинками, переслаивающимися с супе-\nсями и прослоями песка мелкого мощностью до 2.0 м. \nВ мерзлом состоянии суглинки и супеси льдистые — 0.13<Ii<0&40, в юго-\nзападной и юго-восточной части дамбы — сильнольдистые — 0.40<Ii<0.60 с \nлинзами и прослоями льда мощностью до 2,5 м; на отдельных участках в ниж-", "[стр. 10]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  10\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nней части разреза суглинки массивной криогенной текстуры — Ii<0.03. В талом \nсостоянии суглинки мягкопластичные и тугопластичные. \nВ северо-западной и юго-восточной частях в основании ограждающей \nдамбы скважинами ВН-5403, ВН-2871-2875 вскрыты галечниковые и валунные \nгрунты в интервале глубин 3.0-8.0 м. \nГляциальные отложения-суглинки галечниковые (30-40%) вскрыты сква-\nжинами на отдельных участках на глубине 8.0-20.0 м. Мощность отложений не-\nзначительна — 1.0-2.0 м. \nС поверхности разреза на незанятой прудом части повсеместно распро-\nстранены биогенные отложения - почва и торф, в настоящее время биогенные \nотложения прослеживаются локально, мощностью до 1,0 м. \nСкальные грунты в основании дамбы вскрыты скважинами на глубине 5.6-\n21.0 м, что соответствует абсолютным отметкам 41.0-59.5 м. \nПо результатам выполненных инженерно-геологических изысканий толща \nгрунтов основания сооружения до разведанной глубины 17 м является относи-\nтельно неоднородной по литологическому составу и в ее пределах выделяется \n34 инженерно-геологических элемента. \nГрунты основания дамбы представлены толщей аллювиально-\nделювиальных суглинков слоистой криотекстуры (20-30% льда), текущими при \nоттаивании, с прослоями песка, супеси и галечникового грунта мощностью до 5 \nм. На глубинах от 3 до 15 м четвертичные отложения подстилаются выветре-\nлыми песчаниками. \nФизико-механические характеристики грунтов основания пруда-\nнакопителя приведены в таблице 1. \nОграждающая дамба пруда-накопителя отсыпана из суглинка с линзами \nглыбового материала. В геотермическом отношении до момента формирова-\nния пруда-накопителя описываемая территория располагалась в пределах \nраспространения прерывистной толщи вечномерзлых грунтов мощностью от 12 \nм до 50 м с наличием сквозных гидрогенных таликов под озерами и постоянно \nдействующими водотоками. В результате строительства и эксплуатации пруда-\nнакопителя произошло изменение геокриологических условий: \n- тело существующей ограждающей дамбы, отсыпанной слабофильтру-\nющими суглинками, практически полностью промерзло. Температура \nмерзлых грунтов на глубине 10.0 м от современного рельефа изменяет-\nся от минус 0,4оС до минус 3.4оС;", "[стр. 11]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  11\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nТаблица 1. Физико-механические характеристики грунтов основания", "[стр. 12]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  12\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n- на участках между дамбой и отвалами выемки под пруд-накопитель, под \nтехногенными озерами образовались надмерзлотные талики глубиной \nдо 6 м; \n- под существующим прудом-накопителем образовался сквозной техно-\nгенный талик; \n- в северо-западной части площадки, контур сквозного талика выходит за \nпределы дамбы; \n- в северо-восточной части дамбы в ее основании выявлен сквозной та-\nлик; \n- насыпные грунты дамбы инспекторской автодороги до глубины 3-4 м \nнаходятся в талом состоянии в результате отепляющего воздействия \nводы пруда-накопителя. \nЕстественные грунты основания дамбы за контурами сквозных таликов \nнаходятся в мерзлом состоянии. \nТемпература мерзлых грунтов на глубине 10.0 м изменяется в пределах от \nминус 0.5оС до 1.8оС. \nГидрогеологические условия представляют собой сложную гидрогеологи-\nческую систему и характеризуются наличием в слое сезонного ттаивания \nнадмерзлотных подземных вод, функционирующих в летне-осенний период, \nприурочены к насыпным суглинкам, суглинкам и глинам с коэффициентом \nфильтрации до 0,01 м/сутки. Нижним водоупором здесь являются вечномерз-\nлые грунты. \nВ надмерзлотных подрусловых и радиационно-инфильтрационных тали-\nках подземные воды функционируют круглогодично, приурочены к слабофиль-\nтрующим суглинистым грунтам с коэффициентом фильтрации до 0.1 м/сутки. \nВ летне-осенний период подземные воды надмерзлотных таликов гидрав-\nлически связаны с подземными водами сезоннооттаивающего слоя и пред-\nставляют единый водоносный горизонт. \nПитание подземных вод осуществляется за счет инфильтрации атмо-\nсферных осадков и вод весеннего снеготаяния. Максимальный уровень в пе-\nриод выпадения дождей и весеннего снеготаяния может достигать отметок ре-\nльефа. \nВ подозерных и приозерных гидрогенных таликах подземные воды функ-\nционируют круглогодично, вскрыты скважинами на глубине 11.0-20.0 м, что со-\nответствует абсолютным отметкам 39.1-49.0 м. Водовмещающими грунтами \nслужат пески разнозернистые с коэффициентом фильтрации, колеблющимся \nот 1 до 15 м/сутки в зависимости от грансостава песков. Подземные воды \nнапорные, верхним водоупором служат талые и мерзлые суглинки. Величина", "[стр. 13]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  13\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nнапора достигает 15 м, установившийся уровень зафиксирован на абсолютных \nотметках 52.5-54.5 м. \nВ подозерных таликах, где верхним и нижним водоупором служат сла-\nбофильтрующие талые и мерзлые суглинистые грунты, подземные воды носят \nзастойный режим и не выполняют функций водопроводящих систем. \nПодземные воды, функционирующие в подозерных и приозерных таликах, \nпримыкающих к зоне распространения маломощной толщи вечномерзлых \nгрунтов, гидравлически связаны через окна талых песчаных грунтов с вторым \nводоносным горизонтом, функционирующим в подмерзлотных и сквозных та-\nликах на глубине 17.9-24.0 м, что соответствует абсолютным отметкам 34.0-\n39.4 м. \nПодземные воды приурочены к пескам с коэффициентом фильтрации 1-10 \nм/сутки в зависимости от грансостава и кровле скальных грунтов с коэффици-\nентом фильтрации, колеблющимся от 5 до 15 м/сутки, в зависимости от номен-\nклатурного вида грунтов и степени выветрелости. Водоносный горизонт напор-\nный, верхним водоупором служат талые суглинистые и мерзлые грунты, уста-\nновившийся уровень зафиксирован на абсолютных отметках 40.9-50.4 м. Ос-\nновной областью питания служат эрозионно-тектонические долины со сквоз-\nными таликами, а также окна сквозных таликов, через которые осуществляется \nпереток подземных вод из подозерных таликов. Разгрузка осуществляется в \nрайоне оз.Пясино. \nПо химическому составу подземные воды второго водоносного горизонта \nгидрокарбонатно-кальциевые. \nВ результате строительства и эксплуатации пруда-накопителя гидрогеоло-\nгические условия усложнились. \nВ надмерзлотных и сквозных техногенных таликах подземные воды функ-\nционируют круглогодично, водовмещающими грунтами служат насыпные круп-\nнообломочные ( галечниковые, щебенистые и глыбовые грунты) и галечнико-\nвые грунты с  коэффициентом фильтрации более 20 м/сутки. Водоносный го-\nризонт безнапорный, в зимний период слабонапорный, установившийся уро-\nвень зафиксирован на абсолютных отметках 62.6-64.1 м. \nПитание водоносный горизонт получает за счет инфильтрации техноген-\nных вод из пруда-накопителя через легко-дренируемые вышеперечисленные \nгрунты, где их подошва залегания находится ниже уровня зеркала воды в пру-\nде. Разгрузка техногенных вод из пруда-накопителя происходит через тело \nдамбы только в западной части дамбы по ранее существовавшим гидрогенным \nталикам.", "[стр. 14]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  14\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nГидрогеологические условия характеризуются наличием в сезоннооттаи-\nвающем слое надмерзлотных подземных вод, функционирующих в летне-\nосенний периоды. \nПлощадка пруда-накопителя по схемам 3 и 4 СНиПа II-7-81* относится к \nзоне с сейсмичностью 5 баллов. По данным имеющихся изысканий по физико-\nмеханическим характеристикам грунты в основании дамбы пруда-отстойника \nотносятся к 1 категории по сейсмическим свойствам. В соответствии с табли-\nцей № 1* СНиПа II-7-81* сейсмичность площадки пруда-накопителя с грунтами \n1 категории в основании может быть снижена на 1 балл. В связи с изложенным \nвыше учитывать сейсмические воздействия при расчете устойчивости ограж-\nдающей дамбы пруда-накопителя не требуется.", "[стр. 15]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  15\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n3. СУЩЕСТВУЮЩИЕ СООРУЖЕНИЯ КОМПЛЕКСА ПРУДА-НАКОПИТЕЛЯ \nПруд-накопитель (пруд-отстойник) предназначен для механической очист-\nки и осветления промышленных стоков перед повторным использованием их в \nтехнологическом процессе на обогатительной фабрике. С момента ввода в \nэксплуатацию пруд-накопитель используется как для осветления и очистки \nсливов технологических вод ТОФ, так и в качестве промежуточного накопителя \nпродуктов обогащения с последующей откачкой их в технологический процесс. \nПруд-накопитель принят в эксплуатацию в 1981 г. К настоящему времени \nпруд-накопитель находится в эксплуатации 38 лет. \nПруд-накопитель выполнен по документации, составленной специалиста-\nми управления капитального строительства НГМК во изменение первоначаль-\nного проекта, разработанного институтом \" Механобр\" в 1978 г, шифр 20226-\n401. \nОрганизация, выполнявшая строительные и монтажные работы на пруде-\nнакопителе — СУ \"Строймеханизация\". \nПруд-накопитель ТОФ косогорного типа, выполнен в полувыемке-\nполунасыпи, по способу заполнения – наливной. Водосборная площадь пруда-\nнакопителя составляет ~ 0,26 км2. Класс опасности складируемых продуктов \nобогащения – IV. \n3.1 Основные параметры и характеристики сооружений \nВ настоящее время в состав ГТС пруда-накопителя входят: \n1. Дамба пруда-накопителя, как ограждающее сооружение, высотой \nдо 8,0 м, длиной 1348 м ( чертеж 359335- ГТ, « Норильскпроект», при-\nложение «А»); \n2. Насосная станция оборотной воды — береговая насосная станция с \nзаглубленным машинным залом (-8,0 м) для подачи осветленной обо-\nротной воды из пруда-накопителя на Талнахскую обогатительную \nфабрику (чертежи 30916-ГИ-14; 15, ЗАО «МИ», приложение «Б»); \n3. Сифонный водозабор из двух труб Ду 1000 ( чертеж 358992- ТК0.1, \n«Норильскпроект», приложение «В»); \n4. Водоводы 3 Ду1000 мм, длиной 800 м каждый, для подачи оборотной \nводы в технологический процесс ТОФ; \n5. Земснаряд МЗ-ЗА, плавучий несамоходный землесосный снаряд, \nоборудованный грунтовым насосом ГрУ 800/40, для откачки металло-", "[стр. 16]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  16\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nсодержащего материала из пруда-накопителя в НОВ с дальнейшей \nперекачкой насосами \"Warman\" 6/4 FFY-НH на ТОФ; \n6. Магистральный пульповод Ø 273 мм, длиной 800 м для подачи ме-\nталлосодержащего материала из пруда-накопителя в технологиче-\nский процесс ТОФ. \n7. Самотечные водоводы 2Ду1000 мм от ТОФ в пруд-накопитель. \nСхема сооружений пруда-накопителя приведена на рисунке 1. \nСтроительство ограждающей дамбы осуществлялось по рационализатор-\nскому предложению УКСа комбината \" Изменение конструкции пруда-\nотстойника ОФ-2 Норильского ГМК\", № 181 от 28.12.77 г., согласованному ин-\nститутом \"Механобр\" с соответствующими замечаниями. \nПри этом из первоначального проекта исключили противофильтрацион-\nные устройства (пленочный экран и укладку асфальта). Отстойник был допол-\nнительно заглублен на 1 м, отметки дна выемки котлована составили 56,0 м, \nотметка гребня ограждающей дамбы 65,0 м. Дамба отсыпалась из местного \nгрунта выемки. В период 2016-2018 гг. Производилась отсыпка и уплотнение \nгребня дамбы, верховых и низовых откосов, восстановление пляжа. \nПо инженерно-геологическим изысканиям, выполненным институтом ООО \n«Норильскгеология» \" Технический отчет об инженерно-геологических изыска-\nниях по объекту: « ТОФ. Реконструкция и техническое перевооружение ТОФ с \nувеличением мощности до 18 млн. тонн по сумме руд. Корректировка 3 Пуско-\nвого комплекса» № 356662- ИГ-662. 2018 г., ограждающая дамба отсыпана из \nсуглинка с линзами глыбового материала. \nГрунты основания дамбы представлены толщей аллювиально-\nделювиальных суглинков слоистой криотекстуры (20-30% льда), текущими при \nоттаивании, с прослоями песка, супеси и галечникового грунта мощностью до 5 \nм. На глубинах от 3 до 15 м четвертичные отложения подстилаются выветре-\nлыми песчаниками.", "[стр. 17]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  17\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nРисунок 1.", "[стр. 18]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  18\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nОсновные параметры пруда-накопителя по состоянию на 2010 г.: \n Емкость пруда-накопителя \nТип отстойника — косогорный, наливной. \nПлощадь — 0,061 км2; \nВодосборная площадь ~ 0,26 км2. \nОбъем пруда (вода и шламы) — 0,268 млн.м3; \nПериметр — 1348 м; \nМаксимальная глубина пруда — 6,5 м; \nСредняя глубина — 2÷3 м; \nУровень воды в отстойном пруде — 62,1÷62,5 м; \nТолщина ледового покрова в зимний период — 1,0 м;  \n Ограждающая дамба пруда-накопителя \nТип дамбы — однородная земляная суглинистая.  \nОтметка гребня — 65,0 м; \nДлина напорного фронта — 850 м; \nШирина по гребню — 8,0 м; \nМаксимальная высота — 8,0 м; \nЗаложение низового откоса — от 3 до 1,5; \nСреднее заложение верхового откоса — 2,5; \nПо гребню дамбы имеется автодорога с щебеночным покрытием, толщи-\nной слоя 0,25 м. \nНа дамбе предусмотрены установка контрольно-измерительной аппарату-\nры, освещение и телефонная связь с фабрикой. \nДренажные сооружения по контуру пруда-накопителя не предусмотрены. \nОграждающую дамбу пруда-накопителя можно классифицировать как во-\nдонапорное гидротехническое сооружение высотой 8 м. Максимальный напор \nна дамбу над отметкой ее основания 4,0 м. \nВ соответствии с табл.Б.1 СНиП 33-01-2003 \" Гидротехнические сооруже-\nния. Основные положения \" дамбу пруда-накопителя можно отнести к IV- му \nклассу капитальности. \n3.2 Основные технологические процессы \nОсновной функцией пруда-накопителя является отстаивание поступаю-\nщей жидкой фазы перед повторным использованием в технологии обогати-\nтельной фабрики. Сливы сгустителей содержат незначительное количество \nтвердого, которое не сказывается на заполнении емкости отстойника. В то же \nвремя в пруд-накопитель, расположенный ниже фабрики, направляются пере-\nливы зумпфов системы гидротранспорта продуктов обогащения, которые пла-", "[стр. 19]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  19\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nвучим земснарядом должны возвращаться в сгустители фабрики. Производи-\nтельность системы возврата пульпы на фабрику ~ 500 м3/час, содержание \nтвердого в пульпе 8-10%. \nВ пруд-накопитель поступают технологические сливы, в том числе: \n— сливы сгущения концентратов с металлургических заводов; \n— оборотная вода из хвостохранилища ТОФ (I очередь); \n— сливы сгущения хвостов промпродуктов ТОФ; \n— аварийные переливы зумпфов из пульпонасосной № 1; \n— аварийные опорожнения сгустителей ТОФ. \nСредняя плотность твердого, поступающего в пруд-накопитель, составля-\nет 3,35 т/ м3. Средний объемный вес скелета твердого — 2,0 т/м3. Грануломет-\nрический состав твердого от 70 до 98%  класса — 44 мкм. \nКоличество воды, сбрасываемой в накопитель вместе с твердым, состав-\nляет от 4500 до 5000 м3/час. \nВ составе сточных вод, сбрасываемых в пруд-накопитель, имеются ток-\nсичные вещества: \n— бутиловый аэрофлот — 0,85-4,48 мг/л; \n— бутиловый ксантогенат — 0,57 — 2,28 мг/л; \nГранулометрический, минералогический и химический состав твердого \nприведен в таблице 2. \nТаблица 2 \nГранулометрический, химический и минералогический \nсостав твердого \n№№ Название, характеристики Значение характеристики \n1 Гранулометрический состав: — \nРазмер фракции, мм -0,074 -0,074 \n+0,045 \n-0,045 \n+0,03 \n-0,030 \n+0,019 \n-0,019 \n+0,015 \n-0,015 \n+0,01 \n-0,01 \nСодержание фракции, % 1,32-\n4,18 \n4,34-\n5,6 \n4,5 \n17,3 \n6,0-50 4 4,0-\n18,24 \n18,9-\n61,6 \n2 Минералогический состав:  \nхалькопирит 3,7-7,5  \nпирротин 41,4-50,7  \nпентландит 3,5-5,7  \nМагнетит 3,1-7,3  \nПорода 29,8-48,3", "[стр. 20]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  20\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nТаблица 2 \nОкончание \n№№ Название, характеристики Значение характеристики \n3 Химический состав:  \nNi 1,35-2,38 \nCu 1,52-2,86 \nCo 0,046-0,14 \nS 14,97-20,66 \nFe 30,64-38,97 \nSiO2 15,76-21,42 \nCaO 4,25-5,62 \nMgO 2,72-3,92 \nAl2O3 4,95-6,74 \nХимический состав сточных вод, поступающих в пруд-накопитель, приве-\nден в таблице 3. \nТаблица 3 \nХимический состав сточных вод, сбрасываемых в пруд-накопитель \n№№ \nп.п. \nНазвание характеристики \n(компонента) \nЕдиницы \nизмерения \nЗначение харак-\nтеристики \n1 Водородный показатель рН Ед 6,02-8,91 \n2 Взвешенные вещества мг/дм3 0-385,5 \n3 Сухой остаток при t=105оС мг/дм3 2583,7-3097 \n4 Окисляемость по О2 мг/дм3 61,9-200,6 \n5 Химическое потребление кислорода (ХПК) мг/дм3 — \n6 Биологическое потребление кислорода мг/дм3 — \n7 Жесткость общая мг/дм3 — \n8 Жесткость карбонатная мг/дм3 — \n9 Нефтепродукты мг/дм3 4,3-6,9 \n10 Фенолы мг/дм3 — \n11 Хлориды мг/дм3 — \n12 Сульфаты мг/дм3 1520,6-1741,2 \n13 Силикаты мг/дм3 — \n14 Цианиты мг/дм3 — \n15 Нитриты мг/дм3 — \n16 Нитраты мг/дм3 — \n17 Диоксины мг/дм3 — \n18 Азот аммонийный мг/дм3 —", "[стр. 21]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  21\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nТаблица 3 \nОкончание \n№№ \nп.п. \nНазвание характеристики \n(компонента) \nЕдиницы \nизмерения \nЗначение харак-\nтеристики \n19 Железо общее мг/дм3 — \n20 Поверхностно-активные вещества (ПАВ) мг/дм3 — \n21 Ионы кальция мг/дм3 554,4-689,4 \n22 Ксантагенат мг/дм3 0,57-2,28 \n23 Аэрофлот мг/дм3 0,85-4,48 \n24 ДМДК мг/дм3 0,25-1,64 \nКоличество воды, забираемое из накопителя, составляет 4000-4500 м3/час \n(по данным годового отчета за 2018 г.). \nОборотная вода пруда-накопителя пригодна для использования в техноло-\nгическом процессе. Качество воды регламентировано стандартом предприятия \nСТП 0401.14.39-2-16-89. \nСведения о системе гидротранспорта и оборотного \nводоснабжения \nПроизводственные стоки ТОФ самотеком по железобетонному лотку, пере-\nходящему в трубу Ду1000 м, расположенному в тоннеле, поступают в пруд-\nнакопитель. По второму трубопроводу Ду1000, расположенному параллельно \nпервому, также самотеком поступают сливы сгустителей концентратов с заводов. \nЧерез УП-1(узел переключения №1) по трубопроводу ДУ 400 поступает оборот-\nная вода из хвостохранилища ТОФ (I очередь). Осветление оборотной воды про-\nисходит за счет осаждения твердых частиц в отстойнике, при движении воды в \nсторону водозабора. \nОсветленная вода из пруда-накопителя по сифонам 2 Ду1000 подается в \nнасосную станцию оборотной воды во всас насосов Д-2000/100, производитель-\nностью 2000 м3/час, напором 100 м. В работе находится 3 насоса из шести уста-\nновленных. Из насосной станции оборотная вода подается по трем водоводам Ду \n1000 мм в баки оборотной воды ТОФ. \nНасосная станция — береговая, заглубленного типа, отметка оси насосов \n57,0 м, отметка нуля насосной — 65,0 м. Насосная построена по чертежам инсти-\nтута Механобр, шифр 20226 и проект АО \"Механобр инжиниринг\", шифр 30916-\nГТ-12. \nДля откачки твердых осадков в пруде-накопителе установлен плавучий не-\nсамоходный землесосный снаряд МЗ-ЗА, оборудованный грунтовым насосом \nГРУ-800/40 (производительность 800 м3/час, напор 40м). Земснаряд качает пуль-", "[стр. 22]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  22\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nпу в зумпф НОВ, откуда она по стальному пульповоду Ду 250 мм насосом \n\"Warman\" 6/4 FFY-АH подается в сгустители ТОФ.", "[стр. 23]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  23\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n4. БАЛАНС ВОДЫ В ПРУДЕ-НАКОПИТЕЛЕ  \nБаланс пруда-накопителя, ввиду отсутствия на сегодняшний день прибо-\nров, фиксирующих количественные показатели основных потоков, составлен \nисходя из следующего: \n― фактическая подача оборотной воды из пруда на ТОФ составляет ~ \n4500-5000 м3/час (по данным годового отчета за 2018 г.); \n― при водосборной площади пруда-накопителя ~0,26 км2, количество \nосадков за вычетом испарений, поступающих в пруд-накопитель в раз-\nрезе года при водности года 50% обеспеченности; \n― уровень в пруде-накопителе поддерживается постоянным. \nТаблица 4 \nБаланс пруда-накопителя \n№№ Наименование Ед.изм. \nКоличество \nлетний период зимний период \n А. Водопоступление    \n1 Технологические стоки фабрики \n(средний расход) \nм3/час 4750,0 4750,0 \n2 Водоприток (по среднегодовому \nколичеству осадков) \nм3/час 44,6 0 \n3 Итого: м3/час 4794,6 4750,0 \n Б. Потери    \n4 Фильтрационные м3/час - - \n Б. Водоотведение    \n5 Возврат осветленной воды в \nбаки оборотной воды (\"А\"-\"Б\") \nм3/час 4794,6 4750,0", "[стр. 24]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  24\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n5. ЭКСПЛУАТАЦИЯ СООРУЖЕНИЙ КОМПЛЕКСА ПРУДА-НАКОПИТЕЛЯ \nЭксплуатацией гидротехнических сооружений ТОФ занимается участок \nскладирования металлосодержащих материалов Талнахской обогатитель-\nной фабрики ( УСММ ТОФ). Состав рабочих и ИТР участка складирования \nметаллосодержащих материалов определен штатным расписанием ТОФ. \nГидротехническая служба укомплектована специалистами-гидротехниками. \nК основным условиям эксплуатации относятся: \n1. Соблюдение проектных решений, инструкций, правил и других норма-\nтивных документов, содержащих требования к эксплуатации ГТС и со-\nответствие фактического состояния сооружений пруда-накопителя \nэтим требованиям. \n2. Эксплуатация сооружений пруда-накопителя по утвержденной местной \nинструкции по эксплуатации, разработанной в соответствии с требова-\nниями \" Правил безопасности гидротехнических сооружений накопите-\nлей жидких промышленных отходов\", утвержденных постановлением \nГосгортехнадзора России от 28.01.2002 г. №6. \n3. Своевременное проведение текущих, планово-предупредительных и \nкапитальных ремонтных работ на сооружениях пруда-накопителя. \n4. Выполнение предписаний контролирующих органов, предложений, из-\nложенных в экспертном заключении и лицензионных условиях. \n5. Проведение комиссионных обследований не реже 2 раз в год. \nБезаварийная эксплуатация ГТС пруда-накопителя обеспечивается вы-\nполнением следующих условий: \n- Ведение постоянного контроля за состоянием сооружений в соответ-\nствии с « Проектом мониторинга безопасности ГТС» ( проект ЗАО МИ, \nшифр 33016-23, 2016 г.), обеспечивающего должный уровень безопас-\nности ГТС и соблюдение требований по основным диагностируемым \nпараметрам. \n- Профессиональная подготовка и своевременное повышение квалифи-\nкации персонала, обслуживающего комплекс сооружений пруда-\nнакопителя. \nПеречень работ по ведению контроля и наблюдений за состоянием \nсооружений пруда-накопителя приведен в главе 6. \n5.1 Ограждающая дамба \nЭксплуатация ограждающей насыпной дамбы заключается в ведении ре-\nгулярных визуальных и инструментальных наблюдений, направленных на под-", "[стр. 25]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  25\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nдержание ее в надежном состоянии, определяемом критериями безопасности \nсооружения, приведенными ниже. При отклонении от этих критериев проводят-\nся мероприятия по восстановлению ее надежности. \nОсновными работами по поддержанию дамбы в рабочем состоянии явля-\nются следующие: \n― планировка гребня дамбы и ее откосов при обнаружении оползней \nили размывов в результате обильных дождей или порыва трубопро-\nводов, проложенных по гребню северного участка дамбы; \n― поддержание гребня дамбы на проектной отметке 65,0 м. \nРемонтные работы по дамбе: \n1. Ремонт дамбы и ее откосов следует производить в кратчайшие сроки, \nесли обнаруживаются размывы низового откоса или просадки гребня дамб с \nпоследующей рихтовкой труб. \n2. Понижения поверхности гребня и откосов дамбы, а также поперечные \nтрещины, обусловленные просадками и осадками тела и основания дамбы, \nликвидируются путем заполнения их металлургическим шлаком или хвостами. \n3. Если на гребне дамбы образовалась промоина за счет протечки или \nразрыва трубопровода, то восстановить дамбу можно ограждением промоины \nперемычкой со стороны верхового откоса дамбы с последующей заделкой \nпромоины насухо металлургическим шлаком или хвостами. \n4. Ограждающая перемычка должна быть выполнена в виде наброски \nмешков с хвостами при помощи бульдозера или экскаватора. \nПосле возведения перемычки и заделки промоины отремонтированный \nучасток следует замыть хвостами. \n5. Приемка ремонтных работ оформляется актом и отражается в паспор-\nте сооружения. \n6. Для проведения работ должны быть назначены ответственные испол-\nнители. \n7. Все работы должны производиться при достаточном освещении с со-\nблюдением инструкции по технике безопасности, составленной на основании \nСНиПов 12-03-2001 и 12-04-2002 \"Безопасности труда в строительстве\". \n8. Устанавливать краны для работы на свеженасыпанном неуплотнен-\nном грунте, а также на площадке с уклоном больше, чем указано в паспорте \nкрана, не допускается. \nЗапрещаются разработка и перемещение грунта бульдозерами, \nскреперами, грейдерами при движении на подъем или под уклон с углом \nнаклона больше указанного в паспорте машины.", "[стр. 26]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  26\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nПри работе двух и более бульдозеров расстояние между ними должно \nбыть не менее 15 м. \nДвижением машин на дамбе при подаче грунта автотранспортом должно \nуправлять специально выделенное для этой цели лицо. \nЭкскаваторы во время работы должны устанавливаться на \nспланированной горизонтальной площадке и во избежание самопроизвольного \nперемещения закрепляться инвентарными упорами. \nПри работе экскаватора не разрешается производить другие работы и \nнаходиться в радиусе действия экскаватора плюс 5 м. \nПри работе на откосах необходимо принимать меры безопасности против \nскольжения и падения людей (стремянки, предохранительные пояса и др.). \nПри подаче на откос грунта запрещается нахождение людей в зоне \nвозможного падения как материала, так и машин. \nВ период производства работ с передвижением механизмов необходимо \nпринимать меры (полив водой т.д.) к пылеподавлению на путях передвижения. \nВ зимнее время перед производством работ на дамбе рабочие места \nдолжны быть очищены от снега и льда. \nКонтроль и наблюдения за состоянием ограждающей дамбы пруда-\nнакопителя проводятся с использованием контрольно-измерительной аппара-\nтуры, установленной на дамбе, и при помощи вторичных приборов и инстру-\nментов (см. раздел 5.5). \n5.2 Насосные установки \nНасосные установки – стационарные в здании насосной станции обо-\nротной воды и несамоходный земснаряд. \nЕжедневное обслуживание насосной станции включает: \nа) очистку механизмов от грязи; \nб) смазку соединений в соответствии с картой смазки; \nв) наблюдение за исправностью световой и звуковой сигнализации; \nг) учет перекачиваемой воды. \nКАТЕГОРИЧЕСКИ ЗАПРЕЩАЕТСЯ: \n― пуск насоса, незаполненного полностью водой; \n― пуск насоса на пустой водовод оборотной воды; \n― пуск насоса при наличии в нем воздуха; \n― пуск насоса при не полностью открытой задвижке на всасе; \n― эксплуатация насоса при температуре подшипника выше 60оС; \n― при работе на закрытую задвижку на напоре следует следить за тем-\nпературой воды внутри насоса. Она не должна превышать 85оС.", "[стр. 27]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  27\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n― регулирование расхода насоса задвижками, установленными на вса-\nсе и напоре, во избежание их быстрого износа и выхода из строя всей \nсистемы;  \n― эксплуатировать насос при неисправности арматуры или отдельных \nдеталей насосного агрегата. \nНа дисплее оператора насосной станции должна быть отражена техноло-\nгическая схема всех электромеханизмов и выделены все находящиеся в дан-\nное время в работе механизмы, а также отражены показания приборов кон-\nтроля, требуемых по техпаспортам установленных электромеханизмов. \nЭксплуатация насосной станции должна вестись в соответствии с местной \nинструкцией по эксплуатации и инструкцией по эксплуатации насосных устано-\nвок, в частности Д2000/100, ГрУ-800/40 и Warman 6/4 FFY-НH. \nВ насосной должен вестись учет часов непрерывной и межремонтной ра-\nботы всех основных насосов, как водяных, так и грунтовых. \nУ оператора насосной станции должна быть мобильная связь с диспетче-\nром фабрики ТОФ. \nАварийные ситуации в насосной станции могут возникнуть по следующим \nпричинам: \n― отключение электроэнергии; \n― разрыв или сильные протечки на трубопроводах внутри насосной \nстанции; \n― внезапная остановка электродвигателя насоса или самого насоса; \n― отказ подачи масла в насос и электродвигатель. \nПоследовательность действия обслуживающего персонала должна \nбыть отражена в местной инструкции по эксплуатации насосной. \nДля оптимального режима работы насосных станций рекомендуется: \n― регулярно производить (раз в 2 месяца) осмотр и ревизию всех пуль-\nповых задвижек, не находящихся под давлением, а также задвижек \nсистемы подвода промывочной воды; \n― всегда иметь резервный, готовый к работе насосный агрегат. \nЭксплуатация оборудования, установленного в насосной станции и на \nплавучей насосной, должна производиться в соответствии с техническими \nтребованиями завода-изготовителя и в соответствии с нормами техники без-\nопасности. \nВ помещении насосных станций должны находиться: \nа) технологическая инструкция машиниста;", "[стр. 28]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  28\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nб) выписка из плана ликвидации аварии и порядок действия персонала \nпри аварии на технологически связанных с насосными станциями объ-\nектах; \nв) инструкции по эксплуатации установленного механического, электриче-\nского, подъемно-транспортного оборудования; \nг) журналы учета и контроля работы оборудования. \nНа стенах в пределах ремонтных площадок должны быть вывешены схе-\nмы строповки основного оборудования и грузов, технологические карты выпол-\nняемых ремонтов, правила техники безопасности. \n5.3 Напорные и самотечные трубопроводы \nДля контроля и наблюдения по всей длине трубопроводов необходимо \nнанести четкий пикетаж. \nДля предотвращения разрыва трубопровода Ду 273 ( пульповод) по при-\nчине износа труб необходимо периодически 1 раз в полгода производить заме-\nры толщины их стенок, в четырех местах: сверху, снизу и на уровне их заиле-\nния с обеих сторон. \nПри износе труб до допустимо минимальной толщины произвести поворот \nпульповода на 120º и 180º или выполнить полную замену этого участка пуль-\nповода. \nРасчетная допустимо минимальная толщина стенок пульповодов состав-\nляет 5мм. \nТрубопроводы после ремонта или поворота должны быть испытаны на \nдавление, равное 1,15 рабочего давления. Гидравлические испытания \nвыполняются на участках длиной не менее 1 км. \nЗапрещается производить работы ( сварку, сверление и т.д.), связанные \nс ремонтом пульповодов и арматуры, находящихся под давлением. \nРезервные трубопроводы должны всегда находиться в состоянии, \nпригодном для эксплуатации, и включаться в работу только на время ремонта \nрабочего трубопровода. Резервные трубопроводы должны ежегодно проходить \nревизию на предмет его эксплуатационной пригодности. \nПосле перехода с рабочей нитки на резервную необходимо полностью \nопорожнить рабочий трубопровод. \nОпорожнение трубопроводов производится в следующих случаях: \n разрыв трубы вследствие его чрезмерного износа, гидравлического \nудара, резкого температурного перепада; \n протечка или поломка компенсатора;", "[стр. 29]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  29\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n отключение электроэнергии больше чем на 6 часов в зимний период \nпри температуре воздуха менее -15оС; \n плановая остановка на период ремонта или переключения по техноло-\nгической необходимости. \nПри эксплуатации трубопроводов необходимо: \n для отвода дождевых и талых вод по трассе трубопроводов регулярно \nочищать кюветы, водопропускные трубы под насыпями от снега, льда и нано-\nсов; \n своевременно производить ремонт полотна трассы и рихтовку трубо-\nпроводов в местах деформации основания, а также дорог и подъездов к трас-\nсе; \n немедленно принимать меры по предотвращению протечек; \n следить за целостностью компенсаторов для исключения протечек. \nПротечки устраняются путем подтяжки гаек и шпилек. Если подтяжкой протечки \nне устраняются, компенсатор подлежит замене; \n при замене и установке на трубопроводе новых компенсаторов они долж-\nны быть предварительно испытаны на давление не менее 1,15 рабочего давления; \n проверять работу вантузов, установленных на трассе; \n проводить профилактический осмотр трубопроводов и арматуры и \nвыполнять требования завода-изготовителя по эксплуатации трубопроводной \nарматуры. Наружная часть шпинделей арматуры должна смазываться конси-\nстентной смазкой не реже одного раза в месяц, вся трубопроводная арматура \nдолжна периодически покрываться антикоррозийной краской. \nЗащитные кожухи по трассе трубопроводов предохраняют, в случае \nразрыва, насыпи железных и автомобильных дорог от размыва и серьезных \nразрушений. \nВодопропускные трубы организованно отводят поверхностный сток во \nвремя ливней в ближайший водоток по системе кюветов. \nДля поддержания защитных кожухов и водопропускных труб необходимы: \n регулярный осмотр их и, в случае необходимости, ремонт; \n расчистка кюветов по трассе для свободного пропуска сточных вод. \n5.4 Отстойный пруд \nОсновными задачами эксплуатации отстойного пруда являются следую-\nщие: \n― контроль и наблюдения за уровнем воды в пруде. Нормальный рабо-\nчий уровень – до 62,5 м. Максимальный уровень – 64,0 м;", "[стр. 30]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  30\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n― своевременная разработка отложений металлосодержащих материа-\nлов в пруде-накопителе; \nОтстойный пруд является источником повышенной опасности при \nэксплуатации. Поэтому при проведении работ в акватории отстойного пруда \nпредъявляются особые требования. \nПри работе на воде должен быть организован спасательный пост, \nоборудованный необходимыми спасательными средствами. Все участки \nпроизводства работ на воде, а также плавучие установки должны быть \nобеспечены спасательными средствами. \nНа плавучих средствах, имеющихся на пруде-накопителе, должно быть \nспасательное оборудование и надписи с указанием грузоподъемности. \nВ летний период при выполнении промеров глубин отстойного пруда, а \nтакже для обслуживания сифонных водозаборов все исполнители (не менее 2-\nх человек) должны иметь спасательные пояса. \nВ зимний период, при установившемся ледяном покрове, эти работы \nвыполняются со льда, в соответствии с ПБ 03-438-02 \" Правила безопасности \nгидротехнических сооружений накопителей жидких промышленных отходов\". \nМощность ледяного покрова на пруде достигает 0,61,3 м. \nПри производстве работ в зимнее время предъявляются следующие \nтребования: \n даты начала и конца прохода, проезда и возможного производства ра-\nбот на льду объявляются приказом по ТОФ; \n для определения грузоподъемности ледяного покрова следует ис-\nпользовать данные таблицы 5, составленные для зимнего льда. Прочность \nльда весной уменьшается вдвое. При появлении на льду воды под действием \nнагона ветра расчетная нагрузка на лед должна быть снижена на 50-80%. \nПри расчете принимается только толщина прочных слоев льда; слой снежного \nи пористого, пропитанного водой льда, из общей толщины исключается; \n проход по льду толщиной менее 10 см, а также по недостаточно за-\nмерзшим отложениям хвостов запрещены; \n при наличии на ледяном покрове трещин или при значительных про-\nсадках его, с появлением воды на поверхности, проезд и работа со льда в дан-\nном месте должны быть прекращены;", "[стр. 31]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  31\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n при устройстве в ледяном покрове майны, а также при наличии в ме-\nстах производства работ полыней все опасные для людей места должны \nограждаться и отмечаться знаками, видимыми в дневное и ночное время.  \nТаблица 5 \nДанные для определения ледяного покрова \n№№ \nп/п \nНаименование Вес, \nт \nТолщина речного \nледяного покрова, \nбезопасная при \nтемпературах \nот –5оС до –20оС, \nсм \nМинимальное \nрасстояние \nдо кромки \nльда, \nм \n1 2 3 4 5 \n1 Человек со снаряжением 0,1 10 5 \n2 Автомашина грузоподъемностью \n1,5 т с грузом \n3,5 25 20 \n3 Автомашина с грузом 6,5 35 25 \n4 Автосамосвал с грузом или \nбульдозер \n8,5 40 25 \n5 Автотягач с грузом или трактор 10 40 30 \n6 Трактор с грузом 20 55 30 \n7 Сверхтяжелый груз 40 95 38 \nПримечание: Значение допускаемой толщины льда следует увеличивать в 1,5 при \nтемпературе выше 0оС. \n5.5 Контрольно-измерительная аппаратура \nНа ограждающей дамбе пруда-накопителя имеются 11 поверхностных ма-\nрок, совмещенных с термоскважинами, для ведения геодезического контроля \nза деформациями ограждающей дамбы. \nТемпературный режим грунтов основания и тела дамбы контролируется с \nпомощью 16 термоскважин (Т-1÷Т-11; П-1÷П-5), расположенных на гребне, и 4 \nнаблюдательных скважины (Н-1÷Н-3) в нижнем бьефе дамбы. \nУровень в пруде – с помощью водомерной рейки у сифонного водозабора \nи датчика уровня, установленного в здании НОВ. В насосной станции на трубо-\nпроводах имеются контрольно-измерительные приборы ( манометры, расходо-\nмеры и др.). \nИнструментальные наблюдения выполняются при помощи вторичных при-\nборов и инструментов, типы и потребное количество которых приведены в таб-\nлице 6. \nСхема установки, существующей и проектируемой контрольно-\nизмерительной аппаратуры приведена на рисунке 2.", "[стр. 32]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  32\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nНаблюдение за состоянием контрольно-измерительной аппаратуры (КИА) \nзаключается в следующем: \n― проверка опорного репера по координатам и отметкам должна прово-\nдиться от государственной геодезической сети не реже одного раза в \nтри года. Отметки рабочих реперов следует проверять от опорных \nреперов ежегодно; \n― Термо- и наблюдательные скважины должны быть защищены от за-\nсорения закрывающимися крышками и от повреждения шинами (б/у), \nокрашенными яркими несмывающимися красками, и поддерживаться \nв работоспособном состоянии; \n― металлические части КИА должны быть защищены от коррозии, а на \nвыступающие над поверхностью земли защитные колпаки (трубы) яр-\nкими несмывающимися красками должна быть нанесена нумерация. \nТаблица 6.  \nВедомость вторичных приборов и инструментов. \n№№ пп Наименование Тип Количество Примечание \n1 2 3 4 5 \n1.  Нивелир технический  1 компл.  \n2. Рейки шашечные 3-х метровые РН-05 2 компл.  \n3. Теодолит 3Т5КП 1 компл.  \n4. Координатор  1 компл.  \n5. Специальный лот в виде металличе-\nского диска диаметром 150 мм массой \n1 кг на промерном тросе \n 1 компл.  \n6. Батометр для взятия проб воды на \nхиманализ из пруда \n 1 компл.  \n7.  Лот-свисток или хлопушка на сталь-\nной тарированной ленте \n 1 компл.  \n8. Термодатчики или термометры для \nизмерения температуры в тер-\nмоскважинах \n 2 компл.  \n9. Акустический толщиномер  1 компл.", "[стр. 33]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  33\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nРис. 2 Схема размещения контрольно-измерительной аппаратуры", "[стр. 34]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  34\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n6. КОНТРОЛЬ И НАБЛЮДЕНИЯ ЗА СОСТОЯНИЕМ СООРУЖЕНИЙ \nПРУДА-НАКОПИТЕЛЯ \nДля обеспечения безопасной, устойчивой и надежной эксплуатации всех \nсооружений пруда-накопителя необходимо вести постоянный контроль и \nнаблюдения за режимом их работы, проводить планово-предупредительные \nремонты сооружений и оборудования в установленные сроки. \nКонтроль и наблюдения за состоянием сооружений пруда-накопителя \nдолжен вестись в соответствии с \"Проектом мониторинга безопасности пруда-\nнакопителя Талнахской обогатительной фабрики», шифр 33016-23, разрабо-\nтанным ЗАО \" Механобр инжиниринг\", 2010 г. и в соответствии с \" Правилами \nбезопасности гидротехнических сооружений накопителей жидких промышлен-\nных отходов\", ПБ-03-438-02. \nВ «Проекте мониторинга безопасности…» в соответствии с требованиями \nРД 03-259-98 и РД 03-417-01 определены объекты мониторинга пруда-\nнакопителя, которые должны постоянно контролироваться (таблица 7). \nТаблица 7 \nПеречень объектов мониторинга безопасности гидротехнических \nсооружений \n1 Сооружения напорного фронта ГТС - ограждающая дамба;  \n- основание дамбы; \n- емкость пруда-накопителя с отстойным \nпрудом \n2 Система оборотного водоснабже-\nния  \n- сифонный водозабор; \n- насосная станция оборотной воды; \n- напорные водоводы \n3 Система разработки и гидротранс-\nпорта металлосодержащих матери-\nалов  \n- самотечные и напорные пульповоды; \n- плавучий несамоходный земснаряд; \n- насос \"Warman\" 6/4 FFY-НH с приемным \nзумпфом в НОВ \n4 Система КИА - термоскважины; марки и др. \n5 Технологические процессы - гидротранспорт технологических сливов; \n- осветление оборотной воды \n6 Воздействие на состояние окружа-\nющей среды \n- подземные воды; \n- поверхностные воды  \n7 Состояние службы эксплуатации и \nмониторинга \n- квалификация персонала \n- штатное расписание \n8 Проектная и эксплуатационная до-\nкументация \n- учет, комплектность и сохранность \n9 Материалы, запасные части и тех-\nнические средства для предотвра-\nщения аварий \n- материально-техническое обеспечение", "[стр. 35]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  35\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nГидротехнической службой Центра диагностики ЗФ ведется ведомствен-\nный контроль за техническим состоянием ГТС, а также специализированные \nработы мониторинга в соответствии с действующим \" Проектом мониторинга \nпруда-накопителя\". В состав работ входят инструментальные геодезические \nнаблюдения за изменением пространственного положения дамбы, замеры \nтемператур грунтов, гидрогеологические наблюдения за уровнями воды и \nфильтрацией, ежеквартальные геотехнические обследования хвостохранилищ \nсовместно со службами эксплуатации ГТС. \n1. При визуальном контроле состояния ограждающей дамбы проверяют: \n— насыщение откосов поверхностной водой; \n— появление очагов фильтрации с выносом и без выноса грунта; \n— наличие местных деформаций на откосах и гребне дамбы, просадок, вы-\nпоров или провальных воронок; \n— появление продольных или поперечных трещин на гребне или откосах; \n— наличие пучений, вызванных промерзанием обводненных продуктов обо-\nгащения; \n— наличие промоин, состояние ледяного и снегового покровов. \nРезультаты наблюдений за состоянием дамб мастер УСММ ТОФ фикси-\nрует в журнале визуальных наблюдений два раза в месяц. \nЖурнал визуальных наблюдений регулярно проверяет начальник УСММ \nТОФ.  \n2. Геодезический контроль включает: \n— инструментальные наблюдения за осадками и горизонтальными сме-\nщениями дамбы один раз в год; \n— инструментальные наблюдения за просадками под основанием сифон-\nного водозабора; \n— ежегодную поверку показаний водомерной рейки; \n— наблюдения за горизонтом воды в пруде при помощи водомерной рей-\nки. Результаты измерений фиксируются в журнале. \nОпределение планового и высотного положения ограждающей дамбы вы-\nполняется при проведении маркшейдерских замеров, для которых имеет-\nся закрепленная геодезическая сеть. На гребне дамбы размещаются по-\nверхностные грунтовые марки, установленные на глубину ниже глубины \nпромерзания грунтов и предназначенные для измерения осадок. \nОпорный репер, установленный на коренном берегу, привязан к государ-\nственной геодезической сети. Проверка привязки опорного репера произ-\nводится не реже 1 раза в 5 лет.", "[стр. 36]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  36\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n3. Наблюдения за фильтрационным режимом включают определение поло-\nжения уровней фильтрационных вод в теле ограждающей дамбы, величи-\nны фильтрационного расхода на низовом откосе и химического состава \nфильтрационных вод. \nВ проекте мониторинга, выполненного ФГУП ВИОГЕМ в 2002 году, была \nпредусмотрена установка 2- х пьезометров. При бурении скважин под них \n(глубиной 11 м) грунтовые воды не были обнаружены. В существующих \nтермоскважинах вода также отсутствует. Поэтому контроль за фильтраци-\nонным режимом дамбы ограничивается визуальным наблюдением – от-\nсутствие выхода воды на поверхность низового откоса. \nОтбор проб оборотной воды производится ежемесячно. Отбор проб филь-\nтрационной воды на химический анализ производится один раз в год из \nзон повышенной фильтрации. \nОрганизация работ по наблюдениям за фильтрационным режимом осу-\nществляется ГС ЦД, наблюдения проводятся службой УСММ ТОФ с при-\nвлечением сотрудников ГС ЦД. \n4. Замеры температур проводятся в термоскважинах сотрудниками службы \nгеотермических измерений ГС ЦД один раз в квартал. \nТемпературные наблюдения грунтов дополняются замерами температур \nводы в прудковой зоне, на участках сосредоточенной фильтрации.  \nВ нижнем бьефе ограждающей дамбы предусмотрена установка наблюда-\nтельных скважин для гидрогеологических наблюдений за уровнем и физи-\nко-механическими характеристиками грунтовых вод. \nРезультаты наблюдений заносятся в специальный журнал.  \nНаблюдения за заполнением емкости пруда проводятся службой УСММ \nТОФ, для этого: \n— ежедневно фиксируется уровень воды в пруде-накопителе; \n— контролируется объем воды, поступающей на ТОФ; \n— раз в год ( перед началом весеннего паводка) выполняются промеры \nглубин прудка. \nДля определения уровня воды в отстойном пруде установлена водомер-\nная рейка. Поверка показаний водомерной рейки выполняется ежегодно, \nперед весенним паводком, инженером-геодезистом ГС ЦД.", "[стр. 37]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  37\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nТаблица 8, стр.1.", "[стр. 38]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  38\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nТаблица 8, стр.2", "[стр. 39]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  39\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nТаблица 8, стр.3", "[стр. 40]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  40\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nПо результатам проводимых маркшейдерских съемок ГТС выполняются \nисполнительные материалы: построение исполнительного профиля по оси \nограждающей дамбы; построение поперечников с указанием всех геометриче-\nских параметров сооружений в закрепленных створах, а также в местах обна-\nруженных отклонений от проекта, с указанием уровня воды. \nПериодичность работ по контролю за эксплуатацией пруда-накопителя \nприведена в таблице 8 « Ведение мониторинга безопасности на пруде-\nнакопителе ТОФ».", "[стр. 41]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  41\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n7. КРИТЕРИИ БЕЗОПАСНОСТИ ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЙ \nВ проекте \" Критерии безопасности гидротехнических сооружений пруда-\nнакопителя ТОФ \" определены предельно-допустимые значения контролируе-\nмых параметров состояния существующих гидротехнических сооружений пру-\nда-накопителя, по которым производится оценка соответствия состояния гид-\nротехнических сооружений установленным нормам и правилам безопасности \nгидротехнических сооружений. \nОсновными условиями безопасной эксплуатации гидротехнических соору-\nжений пруда-накопителя являются: \n— обеспечение устойчивости и фильтрационной прочности ограждающей \nдамбы; \n— соблюдение технологии эксплуатации; \n— соблюдение основных проектных параметров ограждающей дамбы: \nвеличины предельно-допустимого превышения гребня ограждающей \nдамбы над уровнем воды в пруде, наличие свободной емкости в па-\nводковый период; \n— надежная работа водозаборных сооружений, от надежного состояния \nкоторых зависит безопасность пруда-накопителя, а выход из работы \nможет привести к аварийной ситуации, связанной с переполнением ем-\nкости; \n— целостность напорных и самотечных трубопроводов, проложенных по \nгребню ограждающей дамбы. Неконтролируемые порывы трубопрово-\nдов могут создать аварийную ситуацию: привести к местному размыву \nгребня ограждающей дамбы, переливу через гребень и образованию \nпрорана; \n— ведение качественного мониторинга за состоянием ГТС. \nКонтролируемые показатели состояния ГТС и условий его эксплуатации \nхарактеризуют напряженно-деформированное состояние ГТС, фильтрацион-\nный, температурно-влажностный и гидравлический режимы в сооружениях, их \nоснованиях и береговых примыканиях, параметры нагрузок и воздействий, а \nтакже уровень эксплуатационного состояния. \nСостав контролируемых показателей состояния ГТС и критериев безопас-\nности, определенный на основе результатов расчетов и экспериментальных \nисследований, разработан в проекте « Критерии безопасности гидротехниче-\nских сооружений пруда-накопителя ТОФ», шифр 33016-22, ЗАО МИ, 2010 год. \nОсновными параметрами безопасной эксплуатации пруда-накопителя на \nсегодняшний день являются:", "[стр. 42]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  42\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n— соблюдение заложения низового откоса не менее 1:2,5; \n— превышение отметки гребня намывного пляжа над уровнем воды ( при \nНПУ) в пруде не менее 2,5 м; \n— отсутствие суффозии и оплывания низового откоса в местах выхода \nфильтрационных вод и водопроявлений; \n— отметка гребня ограждающей дамбы 65.0 м.", "[стр. 43]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  43\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n8. МЕРОПРИЯТИЯ ПО ПРЕДУПРЕЖДЕНИЮ ЧРЕЗВЫЧАЙНЫХ \nСИТУАЦИЙ \nОсновная опасность при эксплуатации пруда-накопителя связана с воз-\nможностью возникновения гидродинамических аварий. \nГидродинамическая авария на пруде-накопителе может возникнуть только \nпри условии, если ограждающая дамба утратит свое функциональное назначе-\nние, заключающееся в том, чтобы удерживать от растекания находящиеся в \nпруде-накопителе воду и шламы, или при разрыве трубопроводов с местным \nразмывом низового откоса ограждающей дамбы, а также в результате дей-\nствий обслуживающего персонала или внешнего воздействия. \nВозможные источники опасности для ГТС следующие: \n- Длительное нарушение работы системы водозабора и откачки обо-\nротной воды; \n- Несвоевременная уборка металлосодержащего материала; \n- Отсутствие контроля за балансом воды пруда-накопителя; \n- Разрыв магистрального пульповода. \nРазрушение дамбы в результате внешнего воздействия не связаны с \nуровнем эксплуатации и конструкцией гидротехнических сооружений пруда-\nнакопителя. Эти воздействия могут быть различного рода, например, техноген-\nных происшествий, природных катаклизм, социально-общественных актов и \nдействий. \nПо отношению к последствиям нарушения функционального назначения \nгидротехнических сооружений можно выделить два вида аварийных ситуаций: \n— К первому виду должны быть отнесены аварии, связанные с по-\nследствиями, вызванными разрушением ограждающих дамбы пруда-\nнакопителя и вытеканием металлосодержащих материалов и воды. При \nэтом может быть подтоплена территория, прилегающая к пруду-\nнакопителю, что приведет к остановке предприятия, в отдельных случаях \nмогут иметь место человеческие жертвы. \n— Ко второму виду должны быть отнесены аварийные ситуации, свя-\nзанные с выходом из строя отдельных сооружений и систем, которые не \nнаносят ущерба внешним объектам, но приводят к остановке (приостанов-\nке) производства (затопление механизмов насосных, выход из строя систе-\nмы электроснабжения). \nВозможными причинами аварийных ситуаций, приводящими к разрушению \nдамбы, могут являться:", "[стр. 44]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  44\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n– воздействия природного характера ( ливневые дождевые осадки, вет-\nровые волны и т.п.); \n– воздействия технического характера ( отказы и неполадки оборудова-\nния, конструкций и трубопроводов); \n– ошибочные действия персонала; \n– террористический акт. \nПри возникновении ( реализации) указанных выше источников опасности, \nкак в отдельности, так и одновременно, могут привезти к гидродинамической \nаварии, возможные сценарии которой следующие: разрушение ограждающей \nдамбы и образование прорана вследствие либо потери устойчивости, либо пе-\nрелива через гребень. \nВ случае гидродинамической аварии, связанной с разрушением дамбы, \nбудет иметь место затопление пульпой долины реки Талнах в нижнем бьефе \nдамбы с южной стороны пруда-накопителя. \n«Федеральное государственное бюджетное учреждение Всероссийский \nнаучно-исследовательский институт по проблемам гражданской обороны и \nчрезвычайных ситуаций ( федеральный центр науки и высоких технологий)» \n(ФГБУ ВНИИ ГОЧС (ФЦ) МЧС России) выполнил Расчет  вероятного вреда, ко-\nторый может быть причинен жизни, здоровью физических лиц, имуществу фи-\nзических и юридических лиц в результате аварии на гидротехнических соору-\nжениях пруда-накопителя Талнахской обогатительной фабрики ПООФ Запо-\nлярного филиала ПАО «ГМК «Норильский никель», в котором определены ве-\nличина возможного ущерба и параметры волны прорыва при гидродинамиче-\nской аварии. В расчете принят сценарий развития гидродинамической аварии \nнаиболее тяжелый по последствиям– переполнение пруда-отстойника, как \nследствие произойдет перелив воды через гребень ограждающей дамбы, что \nприведет к её частичному размыву и максимальному ущербу от аварии. \nНа территории, прилегающей к пруду-накопителю и попадающей в зону \nзатопления в результате гидродинамической аварии объектов жилого фонда \nнет, других предприятий нет, в зону возможного затопления могут попасть \nобъекты недвижимости, принадлежащие самому предприятию.  \nНа участке складирования УСММ ТОФ имеется план ликвидации аварий \nПЛА на пруде-накопителе, который составляется и утверждается ежегодно. В \nплане ликвидации аварий отражены все основные мероприятия и действия \nперсонала при аварии. \nВ имеющемся ПЛА четко расписаны оперативные действия \nэксплуатационного персонала и рассмотрены наиболее характерные для \nданного объекта сценариев предаварийных ( аварийных) ситуаций. В \nприложении к ПЛА имеется лист ознакомления всех, задействованных в", "[стр. 45]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  45\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nоперативных работах лиц из числа руководителей, специалистов и служащих \nЗФ ОАО \"ГМК \"Норильский никель\". \nВ случае возникновения аварийных ситуаций на ГТС эксплуатационный \nперсонал действует в соответствии с ПЛА.  \nС целью обучения ИТР и специалистов, которые будут участвовать \nв ликвидации аварий, проводится техническая учеба на рабочих местах, с \nотработкой практических действий в аварийных ситуациях. Обучение \nспециалистов порядку организации и проведения работ по ликвидации \nаварийных ситуаций и личного в них участия проводит главный инженер ОФ.  \nЗа 10 дней до ввода ПЛА начальник участка должен проводить обучение \nрабочих по ПЛА с соответствующей регистрацией в журнале и отметкой в \nличной карточке инструктажа под роспись. Знание ПЛА должно проверяться не \nреже 1 раза в 6 месяцев. При этом должно проверяться умение работников \nвести технологический процесс в соответствии с нормативно-технической \nдокументацией, проверяться знания порядка действий по предупреждению и \nлокализации аварийных ситуаций в соответствии с требованиями \nтехнологического регламента, инструкций по рабочим местам и ПЛА. \nРаботники должны проходить учебные аварийные тревоги, действуя согласно \nПЛА. По результатам учебных тревог должны проводиться разборы, \nвыявляться недостатки руководителей смен, участка и персонала, намечаются \nмероприятия. При возникновении аварии руководитель работ по ликвидации \nаварий должен оценить оперативную обстановку, создать аварийно-\nспасательную бригаду из числа работников участка и, в случае необходимости, \nпривлечь через технического руководителя организации все нужные для \nликвидации аварии службы и технические средства. Аварийно-спасательные \nбригады должны подчиняться руководителю работ по ликвидации аварии. \nРаз в полугодие проводится целевой инструктаж по технике безопасности \nпри ликвидации последствий аварий, стихийных бедствий и катастроф. \nИнструктаж проводит начальник участка. \nУчебные тревоги по проверке знания персоналом плана ликвидации \nаварий проводятся 2 раза в год. \nДиспетчерская служба ТОФ ПООФ в любое время суток при получении \nсигнала о чрезвычайной ситуации ставит в известность по телефону или \nнарочным о получении такого сигнала должностных лиц ЗФ ОАО « ГМК \n«Норильский никель» в соответствии с приведенным списком: \n1 Норильский ВГСО 13 Зам. начальника ЦГТС и ГТ по \nоборудованию", "[стр. 46]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  46\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n2 Газоспасательная служба 14 Зам. начальника ЦГТС и ГТ по \nэнергооборудованию \n3 Начальник ГСС 15 Начальник отдела ОТ и ПБ и ТОФ \nУПБ и ОТ ЗФ \n4 Пожарная часть 16 Начальник УСММ \n5 \nПроизводственное \nуправление ЗФ ПАО \n«ГМК «НН» \n17 Зам. главного инженера ТОФ по \nэксплуатации ГТС \n6 Управление по делам \nГО и ЧС г. Норильска 18 Главный механик ТОФ \n7 Полиция 19 Главный энергетик ТОФ \n8 Скорая помощь 20 Начальник службы автоматизации \nпроизводства ТОФ \n9 Директор ТОФ 21 Начальник ИФЦ \n10 \nГлавный инженер ТОФ  \n22 \nНачальник отдела энергетическо-\nго надзора и надзора за ГТС по \nНПР  \n11 \nНачальник штаба ГО и \nЧС по делам ГО и ЧС \nбюро ГО и ЧС подраз-\nделений обогатительно-\nметаллургического ком-\nплекса ЗФ \n23 \nТаймырский отдел по надзору в \nсфере природопользования \nУправления Росприроднадзора \nпо Красноярскому краю \n12 Начальник ЦГТС и ГТ 24 Здравпункт \n \nПлан ликвидации аварий УСММ ТОФ соответствует фактическому \nположению на пруде-накопителе и обеспечивает безопасные условия работы \nтехнологического и другого персонала при спасении людей и ликвидации \n(локализации) возможных аварий. В имеющемся ПЛА четко расписаны \nоперативные действия эксплуатационного персонала и рассмотрены наиболее \nхарактерные для данного объекта сценариев предаварийных ( аварийных) \nситуаций. В случае возникновения аварийных ситуаций на ГТС \nэксплуатационный персонал действует в соответствии с ПЛА. \nВ \"Плане ликвидации аварий на объектах пруда-накопителя\" рассмотрены \nпричины возникновения аварий, мероприятия по ликвидации аварий и спасе-", "[стр. 47]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  47\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nнию людей, определены лица, ответственные за выполнение мероприятий и \nисполнители, определены маршруты эвакуации людей. \nС пруда-накопителя люди увозятся автотранспортом или вездеходами. \nДоставка лиц для ликвидации аварии, а также необходимых средств, произво-\nдится вездеходом и автомобилями с повышенной проходимостью. \nНа путях подхода к опасной зоне выставляются посты для контроля за \nпропуском в опасную зону рабочих и ИТР, принимающих участие в ликвидации \nаварии. \nНа складе участка постоянно и в исправном состоянии находятся средства \nспасения людей: веревки, предохранительные пояса, инструмент. \nВрач медицинского пункта немедленно выезжает по вызовам, оказывает \nпервую медицинскую помощь пострадавшим, руководит отправкой пострадав-\nших в больницу, организует непрерывное дежурство медицинского персонала \nна все время ликвидации аварии и спасательных работ. \nВ \"Плане ликвидации аварий на объектах пруда-накопителя\" рассмотрены \nпричины возникновения аварий, мероприятия по ликвидации аварий и спасе-\nнию людей, определены лица, ответственные за выполнение мероприятий и \nисполнители, определены маршруты эвакуации людей. \nВ ПЛА разработаны меры по ликвидации аварийных ситуаций по каждому \nварианту с указанием требуемого объема материально-технического обеспе-\nчения. В ПЛА предусматриваются типовые конструктивно-технологические ре-\nшения по предотвращению аварий, рассмотрены наиболее характерные и ве-\nроятные сценарии развития чрезвычайных ситуаций. Эти решения подкрепле-\nны материально-техническим обеспечением. \nК сооружениям пруда-накопителя имеется подъездная автодорога от \nплощадки Талнахской обогатительной фабрики. \nДороги, мосты и подъезды в районе пруда-накопителя расчищены и нахо-\nдятся в работоспособном состоянии. \nПодъезд автотранспортных средств и механизмов ко всем гидротехниче-\nским сооружениям и пульповодам обеспечен в любое время года. \nУчасток пруда-накопителя обеспечен в полном объеме необходимыми \nстроительными механизмами и материалами для ликвидации или локализации \nповреждений и аварийных ситуаций. \nНаличие необходимых строительных механизмов и материалов, наличие \nаварийной бригады, обученность персонала способам защиты и действий при \nавариях обеспечат готовность предприятия к локализации и ликвидации ава-\nрийных ситуаций.", "[стр. 48]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  48\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n9. ШТАТЫ \nЭксплуатация ГТС пруда-накопителя осуществляется работниками участ-\nка складирования металлосодержащих материалов ТОФ ( УСММ). Состав ра-\nбочих и ИТР определен штатным расписанием ТОФ (см. таблицу 9). \nТаблица 9. \nЭксплуатационный персонал \n№№ \nп/п Название штатной единицы \nКвалификацион-\nный разряд \nКоличество штатных \nединиц \n(образование) фактически проект. \n1 Начальник участка Инженер  среднее \n-техническое 1 1 \n2 Машинист землесосного плавучего \nнесамоходного снаряда 5р. 15 15 \n3 Машинист насосных установок 4 р. 6 6 \n   Всего: 22    \n \nЭксплуатационный персонал должен обеспечивать: \nа) бесперебойную работу системы внешнего водоснабжения ТОФ; \nб) безаварийную работу оборудования, арматуры и трубопроводов; \nв) защиту окружающей среды от загрязнения; \nг) соблюдение техники безопасности. \nТакже штатами цеха самостоятельно выполняется часть строительных \nработ. \nДля постоянного контроля за сооружениями пруда-накопителя и наблю-\nдениями к штатам подключена группа геотехнического контроля гидротехниче-\nской службы Управления по надзору за состоянием оснований и фундаментов \nЗФ ОАО « ГМК «Норильский никель» (ГС ЦД). Количественный состав службы \n(по штату) – 6 ИТР, 2 рабочих. В составе гидротехнической службы: 2 гидро-\nгеолога, 1 гидротехник, 1 гидролог, 1 геодезист, 1 физик-эколог.", "[стр. 49]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  49\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nУзкоспециализированные работы (химанализы, термометрия, гидрогеоло-\nгические исследования, метеорология) и технический контроль эксплуатацион-\nной надежности и безопасности ГТС пруда-накопителя осуществляется работ-\nниками УСММ ТОФ и ГС ЦД с привлечением специализированных подразде-\nлений ЗФ ОАО «ГМК «Норильский никель» и сторонних организаций. \nВсе рабочие подразделения цеха при поступлении на работу должны \nпройти предварительное обучение технике безопасности по специальной про-\nграмме с отрывом от производства. К самостоятельной работе допускаются \nтолько рабочие, прошедшие обучение данной программе, сдавшие экзамены и \nполучившие права. \nКаждый работник обязан строго выполнять \"Правила техники безопасности\" \nи в случае обнаружения нарушений в техническом состоянии и работе сооруже-\nний, неисправности оборудования и защитных устройств, которые могут пред-\nставлять опасность для людей, оборудования и окружающей среды, должны не-\nмедленно сообщить своему начальнику или вышестоящему руководителю и при-\nнять меры по устранению нарушений в соответствии со своей должностной или \nтехнологической инструкцией. \nРабочие цеха не реже, чем каждые шесть месяцев, должны проходить по-\nвторный инструктаж по безопасности труда и не реже одного раза в год — про-\nверку знаний инструкций по соответствующим профессиям. Результаты про-\nверки должны оформляться протоколом с записью в журнал инструктажа и \nличную карточку рабочего под роспись.", "[стр. 50]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  50\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n10. ЭКСПЛУАТАЦИОННАЯ ТЕХНИКА \nИмеющееся транспортное оборудование и механизмы в цехе обеспечи-\nвают эксплуатацию систем и сооружений пруда-накопителя. \nПарк машин приведен в таблице 10. \nТаблица 10 \nЭксплуатационная техника \n№№ \nп/п \nНазвание (тип) \n механизма (машины) \nКол-во техники \nфактическое, шт. \nВиды работ, на которых исполь-\nзуются механизмы \n1 Вездеход ГАЗ-71 1 Доставка грузов, персонала, пе-\nрестроповка земснаряда, букси-\nрование сварочного аппарата \n2 Плавучий несамоход-\nный землесосный \nснаряд МЗ-ЗА \n1 Откачивание твердого осадка \nтехнологических вод обогати-\nтельной фабрики из пруда-\nнакопителя. \n3 Дизельный сварочный \nагрегат \n1 Обеспечение сварочных работ в \nполевых условиях \nКо всем объектам должен быть обеспечен надежный подъезд автотранс-\nпортных средств и механизмов в любое время года. Подъездные дороги долж-\nны не реже одного раза в год подвергаться ремонту. Ширина и конструкция \nпроезжей части дорог должна соответствовать проекту. Схемы движения на \nподъездных дорогах должны быть вывешены на видном месте цеха.", "[стр. 51]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  51\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n11. ОСНОВНЫЕ ПОЛОЖЕНИЯ ПО ТЕХНИКЕ БЕЗОПАСНОСТИ \nЭксплуатация сооружений пруда-накопителя должна производиться по \nутвержденной главным инженером местной инструкции по эксплуатации, раз-\nработанной на основании данного проекта и \" Правил безопасности\" с учетом \n\"Единых правил безопасности\". \nВ местной инструкции должны быть отражены вопросы безопасной эксплу-\nатации оборудования и сооружений всех систем, а также вопросы производ-\nственной санитарии, противопожарной защиты. \nОсновные положения техники безопасности: \n1. Эксплуатация сооружений должна осуществляться обслуживающим \nперсоналом в соответствии с проектом и должностными инструкция-\nми. \n2. Все работники и ИТР должны пройти инструктаж и сдать экзамен по \nтехнике безопасности ответственному лицу. \n3. На участке должны постоянно находиться инструкции по технике без-\nопасности по всем видам работ. \n4. В помещении насосных станций должны быть вывешены инструкции \nпо безопасному обслуживанию насосных агрегатов, схемы трубопро-\nводов, задвижек, вентилей. Запорная арматура должна быть исправ-\nна, а ее обслуживание — безопасным. \n5. На участке \"пруд-накопитель\" должен быть разработан и утвержден \nглавным инженером ГОКа план ликвидации аварий. \nВ районе пруда-накопителя должны быть организованы места хране-\nния материалов и инструментов в количестве и номенклатуре, преду-\nсмотренными планом ликвидации аварий. \n6. Необходимо проводить техническую учебу с обслуживающим персо-\nналом, отрабатывать практически аварийные ситуации, предусмот-\nренные планом ликвидации аварий. \n7. При проведении работ должны соблюдаться следующие правила: \n― все работы должны проводиться при достаточном освещении участка \nработ или в светлое время суток; \n― планировку откосов бульдозером разрешается производить на отко-\nсах не круче указанных в паспорте бульдозера. \nВсе работы должны производится при соблюдении инструкции по технике \nбезопасности, составленной на основании СНиП 12-03-2001, 12-04-2002, ГОСТ \nР12.3.048-2002 \"Техника безопасности в строительстве\".", "[стр. 52]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  52\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nВ соответствии с положением \" Правил безопасности гидротехнических \nсооружений накопителей жидких промышленных отходов\" регулярно произ-\nводится проверка знаний, норм и инструкций, у специалистов раз в три года, \nу рабочих раз в 5 лет. \nОбучение и инструктаж по безопасности труда носит непрерывный мно-\nгоуровневый характер и проводится при: \n— подготовке новых рабочих, вновь принятых, но имеющих профессии и \nпереподготовку рабочих (меняющих профессии); \n— повышении квалификации; \n— проведении различных видов инструктажа. \nПо характеру и времени проведения инструктажи подразделяются на: \n Вводный — инструктаж проводит инженер по технике безопасности \nпо программе, разработанной отделом охраны труда; \n Первичный — со всеми вновь принятыми на предприятие по про-\nграмме, разработанной руководителями производства и структур. \nПрограмма согласовывается с отделом охраны труда и техники без-\nопасности; \n Повторный инструктаж проводится не реже одного раза в 6 месяцев и \nпроводится руководителем работ; \n Внеплановый инструктаж. Проводит руководитель предприятия. Объ-\nем и содержание инструктажа определяют в каждом конкретном слу-\nчае в зависимости от причин и обстоятельств, вызывающих необхо-\nдимость его проведения; \n Целевой — при выполнении разовых работ; \n Текущий инструктаж — постоянный перед началом смены. О прове-\nдении текущего инструктажа рабочих делаются записи в журнал вы-\nдачи сменных заданий. При текущем инструктаже исполнителей зна-\nкомят с порядком ведения работ согласно картам безопасности, с \nбезопасным применением инструментов, со средствами индивиду-\nальной защиты, противопожарной подготовкой; \n Инструктаж трудящихся, имеющих разъездной характер работы. \nОтветственность за организацию своевременного и качественного обуче-\nния и проверку знаний в целом возложена на начальника УСММ ТОФ. \nУправление охраны труда и техники безопасности ЗФ ПАО « ГМК « Нориль-\nский никель» подчиняется непосредственно Заместителю Директора по промыш-\nленной безопасности и охране труда ЗФ ПАО «ГМК «Норильский никель». В От-\nделе ПБиОТ Талнахской обогатительной фабрики (Департамент промышленной", "[стр. 53]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  53\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nбезопасности и охраны труда) фабрики имеется журнал регистрации несчастных \nслучаев на производстве. \nСистема мероприятий по проведению сбора данных о травматизме и аварий-\nности на пруде-накопителе основывается на \"Положении о порядке расследова-\nния и учета несчастных случаев на производстве\". \nОтветственность за организацию и своевременное расследование и учет \nнесчастных случаев, разработку и реализацию мероприятий по устранению при-\nчин этих несчастных случаев несет работодатель. \nО всех несчастных случаях со смертельным исходом ЗФ ПАО «ГМК «Нориль-\nский никель» должен сообщать государственной инспекции труда по Краснояр-\nскому краю, которая в свою очередь информирует Федеральную инспекцию труда \nРоссийской Федерации. \nСведения при возникновении чрезвычайных ситуаций на пруде-накопителе \nдолжны немедленно передаваться в контролирующий орган: управление по де-\nлам гражданской обороны и чрезвычайным ситуациям города Норильска и в Ени-\nсейское управление Ростехнадзора РФ. \nЗа период эксплуатации пруда-накопителя случаев травматизма трудящихся и \nаварий не наблюдалось.", "[стр. 54]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  54\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \nПРИЛОЖЕНИЯ \nПриложение «А» - чертеж 359335-ГТ, «Норильскпроект»", "[стр. 55]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  55\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n \nПриложение «Б» - чертежи 30916-ГИ-14; 15, ЗАО «МИ»", "[стр. 56]\nЗАО “МЕХАНОБР ИНЖИНИРИНГ”         33016 – 25 – РХХ  56\nСкиргайло В.В  C:\\Users\\KupriyanovDS\\Desktop\\ Новая папка\\ТОФ\\пруд\\Проект эксплуатации_корректировка пруд ТОФ_2019..doc \n \nПриложение «В» - чертеж 358992-ТК0.1, «Норильскпроект»"]};
